shader_type sky;

uniform vec4 void_base_color : source_color = vec4(0.02, 0.01, 0.05, 1.0);
uniform vec4 memory_shimmer_color : source_color = vec4(0.6, 0.5, 0.8, 1.0);
uniform vec4 hope_glow_color : source_color = vec4(0.9, 0.8, 0.6, 1.0);
uniform float fragment_density : hint_range(0.0, 0.1) = 0.025;
uniform float fragment_scale : hint_range(0.01, 0.5) = 0.1;
uniform float drift_speed : hint_range(0.0, 0.2) = 0.02;
uniform float shimmer_intensity : hint_range(0.0, 2.0) = 1.0;
uniform float turbulence_scale : hint_range(0.1, 10.0) = 3.0;
uniform float turbulence_speed : hint_range(0.0, 1.0) = 0.05;

float hash12(vec2 p) {
    p = fract(p * vec2(5.3983, 5.4427));
    p += dot(p.yx, p.xy + vec2(21.5351, 14.3137));
    return fract(p.x * p.y * 95.4337);
}

vec3 _process_sky() {
    vec3 dir = normalize(VEC_DIR);
    vec2 uv = vec2(atan(dir.z, dir.x) / (2.0 * PI) + 0.5, acos(dir.y) / PI);
    float noise_val = hash12(uv * turbulence_scale + TIME * drift_speed);
    noise_val += hash12(uv * turbulence_scale * 1.5 - TIME * drift_speed * 0.7);
    noise_val *= 0.5;
    vec3 final_color = void_base_color.rgb;
    if (noise_val > (1.0 - fragment_density)) {
        float fragment_intensity = smoothstep(1.0 - fragment_scale, 1.0 - fragment_scale * 0.5, noise_val);
        vec3 fragment_blend = mix(memory_shimmer_color.rgb, hope_glow_color.rgb, fragment_intensity * shimmer_intensity);
        final_color = mix(final_color, fragment_blend, fragment_intensity);
    }
    return final_color;
}

shader_type spatial;
render_mode unshaded;

uniform vec4 primary_color : source_color = vec4(0.02, 0.0, 0.03, 1.0);
uniform vec4 weave_color : source_color = vec4(0.1, 0.05, 0.15, 0.8);
uniform float weave_density : hint_range(0.0, 10.0, 0.1) = 2.0;
uniform float weave_thickness : hint_range(0.0, 1.0, 0.01) = 0.005;
uniform float noise_speed : hint_range(0.0, 1.0, 0.01) = 0.02;
uniform float distortion_strength : hint_range(0.0, 1.0, 0.01) = 0.05;

float rand(vec2 co){ return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453); }
float snoise(vec2 p) { vec2 ip = floor(p); vec2 fp = fract(p); fp = fp*fp*(3.0-2.0*fp); float bl = rand(ip); float br = rand(ip + vec2(1.0, 0.0)); float tl = rand(ip + vec2(0.0, 1.0)); float tr = rand(ip + vec2(1.0, 1.0)); return mix(mix(bl, br, fp.x), mix(tl, tr, fp.x), fp.y); }

void fragment() {
    vec2 uv = SCREEN_UV;
    vec2 current_uv = uv;
    vec2 noise_offset = vec2(snoise(current_uv * 5.0 + TIME * noise_speed), snoise(current_uv * 5.0 + TIME * noise_speed + 10.0));
    current_uv += noise_offset * distortion_strength;
    vec2 grid_uv = current_uv * weave_density;
    vec2 grid_fract = fract(grid_uv);
    float line_x = smoothstep(0.5 - weave_thickness, 0.5 + weave_thickness, grid_fract.x);
    float line_y = smoothstep(0.5 - weave_thickness, 0.5 + weave_thickness, grid_fract.y);
    float weave_pattern = 1.0 - (line_x * line_y + (1.0 - line_x) * (1.0 - line_y));
    float swirl_noise = snoise(current_uv * 10.0 + TIME * noise_speed * 0.5);
    weave_pattern += swirl_noise * 0.1;
    vec4 final_color = mix(primary_color, weave_color, clamp(weave_pattern, 0.0, 1.0));
    ALBEDO = final_color.rgb;
    ALPHA = final_color.a;
}

extends ShaderMaterial

shader_type spatial;
render_mode unshaded;

uniform vec4 void_color : source_color = vec4(0.02, 0.0, 0.05, 1.0);
uniform vec4 nebula_color : source_color = vec4(0.1, 0.05, 0.2, 1.0);
uniform vec4 memory_glow_color : source_color = vec4(0.8, 0.7, 0.9, 1.0);
uniform float memory_glow_intensity = 0.5;
uniform float memory_pulse_speed = 0.2;
uniform sampler2D noise_texture;
uniform float noise_scale = 0.005;
uniform float noise_speed = 0.01;

void fragment() {
    vec3 world_pos = VERTEX;
    vec2 uv = world_pos.xy * noise_scale + TIME * noise_speed;
    float noise_val = texture(noise_texture, uv).r;
    vec4 final_color = mix(void_color, nebula_color, noise_val * 0.7);
    float pulse = sin(TIME * memory_pulse_speed) * 0.5 + 0.5;
    final_color.rgb += memory_glow_color.rgb * pulse * memory_glow_intensity * noise_val;
    ALBEDO = final_color.rgb;
    EMISSION = final_color.rgb * 2.0;
}

void vertex() {}

shader_type spatial;
render_mode unshaded;

uniform vec4 dark_color : source_color = vec4(0.05, 0.03, 0.08, 1.0);
uniform vec4 light_color : source_color = vec4(0.12, 0.08, 0.18, 1.0);
uniform float noise_scale : hint_range(0.01, 10.0) = 0.2;
uniform float time_speed : hint_range(0.0, 1.0) = 0.005;
uniform float distortion_intensity : hint_range(0.0, 0.1) = 0.002;
uniform float shard_density : hint_range(0.0, 1.0) = 0.01;
uniform float shard_size : hint_range(0.0, 0.01) = 0.0005;
uniform float flicker_speed : hint_range(0.0, 10.0) = 2.0;
uniform float ambient_intensity : hint_range(0.0, 1.0) = 0.05;

float hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }
float noise(vec2 p) { vec2 ip = floor(p); vec2 fp = fract(p); float a = hash12(ip); float b = hash12(ip + vec2(1.0, 0.0)); float c = hash12(ip + vec2(0.0, 1.0)); float d = hash12(ip + vec2(1.0, 1.0)); vec2 u = fp * fp * (3.0 - 2.0 * fp); return mix(mix(a, b, u.x), mix(c, d, u.x), u.y); }

void fragment() {
    vec2 uv = FRAGMENT_COORD.xy / VIEWPORT_SIZE.xy;
    vec2 distorted_uv = uv + sin(TIME * time_speed * 0.5 + uv.x * 5.0) * distortion_intensity;
    distorted_uv += cos(TIME * time_speed + uv.y * 7.0) * distortion_intensity * 0.7;
    float void_noise = noise(distorted_uv * noise_scale + TIME * time_speed * 1.5);
    vec4 final_color = mix(dark_color, light_color, void_noise * void_noise * 0.8);
    vec2 shard_grid_uv = FRAGMENT_COORD.xy / VIEWPORT_SIZE.xy * 300.0;
    vec2 shard_cell = floor(shard_grid_uv);
    float shard_id = hash12(shard_cell);
    if (shard_id < shard_density) {
        vec2 rand_offset = vec2(hash12(shard_cell + vec2(100.0, 0.0)), hash12(shard_cell + vec2(0.0, 100.0))) * 0.8;
        vec2 actual_shard_pos = shard_cell + 0.5 + rand_offset - 0.4;
        float dist_to_shard = distance(shard_grid_uv, actual_shard_pos);
        float shard_alpha = smoothstep(shard_size * 2.0, shard_size, dist_to_shard);
        float flicker = sin(TIME * flicker_speed + shard_id * 50.0) * 0.5 + 0.5;
        shard_alpha *= max(0.0, flicker * flicker * flicker);
        final_color = mix(final_color, vec4(0.8, 0.7, 0.5, 1.0), shard_alpha * 0.7);
    }
    final_color.rgb *= ambient_intensity;
    ALBEDO = final_color.rgb;
    EMISSION = final_color.rgb;
    ALPHA = 1.0;
}

extends ShaderMaterial
shader_type spatial;

render_mode unshaded;
render_mode depth_draw_opaque;

uniform vec4 base_void_color : source_color = vec4(0.01, 0.005, 0.03, 1.0);
uniform vec4 shard_glow_color : source_color = vec4(0.6, 0.8, 1.0, 1.0);
uniform float glow_intensity : hint_range(0.0, 5.0) = 2.5;
uniform float shard_density : hint_range(0.0, 0.1) = 0.03;
uniform float drift_speed : hint_range(0.0, 0.1) = 0.015;
uniform float noise_scale : hint_range(0.1, 10.0) = 0.8;

float hash21(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 43.45); return fract(p.x * p.y); }

void fragment() {
    vec3 world_pos = (WORLD_MATRIX * vec4(VERTEX, 1.0)).xyz;
    vec2 offset = world_pos.xz * noise_scale + TIME * drift_speed;
    float void_texture = hash21(offset);
    vec4 current_color = mix(base_void_color, base_void_color * 1.5, void_texture * 0.2);
    vec2 shard_offset = world_pos.yx * 5.0 + TIME * drift_speed * 5.0;
    float shard_noise = hash21(shard_offset);
    if (shard_noise < shard_density) {
        float shard_effect = smoothstep(0.0, shard_density, shard_noise);
        current_color.rgb += shard_glow_color.rgb * glow_intensity * (1.0 - shard_effect);
    }
    ALBEDO = current_color.rgb;
    EMISSION = current_color.rgb;
    ALPHA = 1.0;
}

shader_type spatial;
render_mode blend_mix, depth_draw_opaque, cull_back, diffuse_lambert, specular_schlick_ggx, hint_screen_texture;

uniform vec4 albedo : source_color = vec4(0.05, 0.05, 0.07, 1.0);
uniform sampler2D noise_texture;
uniform float distortion_strength : hint_range(0.0, 1.0) = 0.1;
uniform float reflection_mix : hint_range(0.0, 1.0) = 0.6;
uniform float time_speed : hint_range(0.0, 5.0) = 0.08;
uniform vec4 emission_color : source_color = vec4(0.1, 0.3, 0.4, 1.0);
uniform float emission_strength : hint_range(0.0, 5.0) = 2.0;

void fragment() {
    vec2 base_uv = SCREEN_UV;
    vec4 noise_sample = texture(noise_texture, base_uv * 2.0 + TIME * time_speed);
    vec2 distorted_uv = base_uv + (noise_sample.rg * 2.0 - 1.0) * distortion_strength;
    vec4 reflection_color = texture(SCREEN_TEXTURE, distorted_uv);
    vec4 void_color = albedo;
    ALBEDO = mix(void_color.rgb, reflection_color.rgb, reflection_mix);
    EMISSION = emission_color.rgb * emission_strength * (noise_sample.r * 0.5 + 0.5);
    ALPHA = 1.0;
}

extends ShaderMaterial
shader_type spatial;

uniform float time_speed = 0.05;
uniform vec4 color_base : source_color = vec4(0.02, 0.0, 0.05, 1.0);
uniform vec4 color_accent : source_color = vec4(0.1, 0.05, 0.15, 1.0);
uniform float shimmer_intensity = 0.1;
uniform float shimmer_speed = 0.2;

void fragment() {
    vec2 uv = SCREEN_UV;
    float t = TIME * time_speed;
    float noise = sin(uv.x * 10.0 + t) * cos(uv.y * 10.0 + t * 0.7);
    noise = abs(noise);
    noise = pow(noise, 2.0);
    vec4 final_color = mix(color_base, color_accent, noise * shimmer_intensity);
    final_color.rgb += sin(TIME * shimmer_speed + uv.x * 5.0 + uv.y * 5.0) * 0.01 * shimmer_intensity;
    ALBEDO = final_color.rgb;
    ALPHA = final_color.a;
}

shader_type spatial;
render_mode unshaded, depth_test_disable, cull_disabled;

uniform float time;
uniform vec3 tint_color = vec3(0.01, 0.005, 0.02);
uniform float emission_strength = 0.7;
uniform float noise_scale = 0.005;
uniform float noise_speed = 0.05;

void fragment() {
    vec2 uv = SCREEN_UV;
    float n = fract(sin(dot(uv + time * noise_speed, vec2(12.9898, 78.233))) * 43758.5453);
    vec3 base_color = tint_color + vec3(n * noise_scale);
    ALBEDO = base_color;
    EMISSION = base_color * emission_strength;
}

